// Extrae el mensaje entrante del payload de WhatsApp Cloud API.
// Devuelve [] para eventos sin mensaje (p. ej. estados "sent"/"delivered"/"read").
const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg) return [];

// Deduplicación: Meta puede reenviar el mismo webhook.
const store = $getWorkflowStaticData('global');
store.processed = store.processed || [];
if (store.processed.includes(msg.id)) return [];
store.processed.push(msg.id);
store.processed = store.processed.slice(-500);

const contactName = value.contacts?.[0]?.profile?.name || '';
let text = '';
let buttonId = '';
let needsAI = true;
let directReply = '';

switch (msg.type) {
  case 'text':
    text = msg.text?.body || '';
    break;
  case 'interactive':
    // Respuesta a botones (p. ej. el consentimiento: consent_si / consent_no) o a una lista.
    buttonId = msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.id || '';
    text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
    break;
  case 'button':
    buttonId = msg.button?.payload || '';
    text = msg.button?.text || '';
    break;
  default:
    // Audio, imagen, documento, ubicación, etc.: se avisa al modelo para que responda según el system prompt.
    text = `[El usuario envió un mensaje de tipo "${msg.type}" que el asistente no puede leer.]`;
}

if (!text.trim()) {
  needsAI = false;
  directReply = 'Disculpe, no pude leer su mensaje. ¿Podría escribirnos su consulta en texto, por favor?';
}

return [{
  json: {
    from: msg.from,
    messageId: msg.id,
    contactName,
    phoneNumberId: value.metadata?.phone_number_id,
    text: text.slice(0, 4000),
    buttonId,
    needsAI,
    directReply,
  },
}];

// Arma la solicitud al LLM (Ollama o Anthropic, según LLM_PROVIDER) con el historial de la conversación.
const fs = require('fs');
// Se lee la salida de la puerta de consentimiento (no $input): los nodos intermedios no deben alterar los datos.
const input = $('Puerta de consentimiento').first().json;

const provider = ($env.LLM_PROVIDER || 'ollama').trim().toLowerCase();
if (!['ollama', 'anthropic'].includes(provider)) {
  throw new Error(`LLM_PROVIDER no válido: "${provider}". Use "ollama" o "anthropic".`);
}

// El system prompt (incluido su "Recordatorio final") vive solo en system_prompt.md.
const promptPath = $env.SYSTEM_PROMPT_PATH || '/data/system_prompt.md';
let systemPrompt;
try {
  systemPrompt = fs.readFileSync(promptPath, 'utf8');
} catch (e) {
  throw new Error(`No se pudo leer el system prompt en ${promptPath}: ${e.message}`);
}
// Estado del consentimiento, al final del recordatorio. Va después del texto fijo para no romper la
// caché del prompt (Ollama reutiliza el prefijo idéntico; Claude cachea el primer bloque).
const consentLine = `Consentimiento: ${input.consentStatus || 'pendiente'}`;

// Memoria simple en static data del workflow (solo persiste en ejecuciones de producción).
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};
const maxTurns = parseInt($env.CONVERSATION_MAX_MESSAGES || '20', 10);
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;

let convo = store.conversations[input.from];
if (!convo || Date.now() - convo.updatedAt > ttlMs) {
  convo = { messages: [], updatedAt: Date.now() };
}

const now = new Date().toLocaleString('es-PE', {
  timeZone: $env.BUSINESS_TIMEZONE || 'America/Lima',
  dateStyle: 'full',
  timeStyle: 'short',
});
const nameNote = input.contactName ? ` | Nombre de perfil en WhatsApp: ${input.contactName}` : '';
const currentTurn = `[Contexto del sistema: fecha y hora actual: ${now}${nameNote}]\n\n${input.text}`;
const messages = [...convo.messages, { role: 'user', content: currentTurn }];

let llmBody;
if (provider === 'anthropic') {
  llmBody = {
    model: $env.ANTHROPIC_MODEL || 'claude-sonnet-5-5',
    max_tokens: parseInt($env.ANTHROPIC_MAX_TOKENS || '8000', 10),
    thinking: { type: 'adaptive' },
    output_config: { effort: $env.ANTHROPIC_EFFORT || 'low' },
    // Si un clasificador de seguridad rechaza la solicitud, la API la reintenta en el modelo recomendado.
    fallbacks: 'default',
    system: [
      { type: 'text', text: systemPrompt, cache_control: { type: 'ephemeral' } },
      { type: 'text', text: consentLine },
    ],
    messages,
  };
} else {
  llmBody = {
    model: $env.OLLAMA_MODEL || 'llama3:latest',
    stream: false,
    keep_alive: $env.OLLAMA_KEEP_ALIVE || '30m',
    options: {
      temperature: parseFloat($env.OLLAMA_TEMPERATURE || '0.3'),
      num_ctx: parseInt($env.OLLAMA_NUM_CTX || '8192', 10),
      num_predict: parseInt($env.OLLAMA_NUM_PREDICT || '512', 10),
    },
    messages: [{ role: 'system', content: `${systemPrompt.trimEnd()}\n\n${consentLine}\n` }, ...messages],
  };
}

return [{ json: { ...input, provider, llmBody, history: convo.messages, maxTurns } }];

// Procesa la respuesta del LLM (Ollama o Anthropic), extrae el bloque <cita>, aplica el filtro de
// consentimiento y actualiza la memoria.
const res = $input.first().json;
const ctx = $('Preparar solicitud LLM').first().json;

const FALLBACK = 'Disculpe, en este momento no puedo procesar su mensaje. Un miembro de nuestro equipo le contactará en horario de atención. Gracias por escribir a JS CONSULTORES Y ABOGADOS.';
const REFUSAL = 'Disculpe, no puedo ayudarle con esa solicitud por este medio. Si lo desea, puedo coordinar una consulta con el equipo del estudio.';

let reply = '';
let ok = false;

if (res.error) {
  // LLM caído, modelo no descargado, clave inválida o tiempo de espera agotado.
  reply = FALLBACK;
} else if (ctx.provider === 'anthropic') {
  if (res.stop_reason === 'refusal') {
    reply = REFUSAL;
  } else if (Array.isArray(res.content)) {
    // Solo bloques de texto: la respuesta puede incluir bloques "thinking" que no se envían.
    reply = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
    ok = true;
  }
} else if (res.message && typeof res.message.content === 'string') {
  reply = res.message.content;
  ok = true;
}

reply = reply.replace(/<think>[\s\S]*?<\/think>/g, '').trim(); // por si se usa un modelo con razonamiento visible
if (!reply) { reply = FALLBACK; ok = false; }

// Extraer la solicitud de cita, tolerando bloques de código alrededor. Si el modelo emitió varios
// bloques se usa el último válido, y se retiran todos del mensaje visible.
const CITA_RE = /(```[a-z]*\s*)?<cita>([\s\S]*?)<\/cita>(\s*```)?/gi;
const parseCita = (raw) => {
  raw = raw.trim();
  try { return JSON.parse(raw); } catch (e) {}
  const obj = raw.match(/\{[\s\S]*\}/);
  try { return obj ? JSON.parse(obj[0]) : { raw }; } catch (e) { return { raw }; }
};
let appointment = null;
for (const m of reply.matchAll(CITA_RE)) {
  const parsed = parseCita(m[2]);
  if (!appointment || !parsed.raw || appointment.raw) appointment = parsed;
}
if (appointment) {
  reply = reply.replace(CITA_RE, '').trim();
}
// Etiquetas <cita> sueltas o sin cerrar: no mostrarlas al usuario.
reply = reply.replace(/<\/?cita>[\s\S]*$/i, '').trim();
if (!reply && appointment) {
  reply = 'Gracias, he registrado su solicitud. Un miembro de nuestro equipo le confirmará la cita en horario de atención.';
} else if (!reply) {
  reply = FALLBACK;
  ok = false;
}

if (reply.length > 4000) reply = reply.slice(0, 3990) + '…';

const consented = ctx.consentStatus === 'otorgado';
let waMessage = { type: 'text', text: { preview_url: false, body: reply } };

// Filtro de salida (Ley N.° 29733): sin consentimiento otorgado, si la IA pide nombre, correo, DNI,
// teléfono o dirección, se reemplaza su respuesta por el mensaje de consentimiento con botones.
const DATA_WORD = /(nombre|apellido|correo|e-?mail|\bdni\b|documento de identidad|tel[eé]fono|celular|n[uú]mero de contacto|direcci[oó]n|domicilio)/i;
const REQUEST = /(ind[ií]queme|ind[ií]quenos|ind[ií]came|me (indica|brinda|proporciona|comparte|da|facilita|dice|deja|escribe|env[ií]a)|br[ií]ndeme|proporci[oó]neme|comp[aá]rtame|facil[ií]teme|d[eé]jeme|d[eé]jenos|env[ií]eme|escr[ií]bame|podr[ií]a (darme|indicarme|brindarme|compartir|proporcionar|dejarnos|enviarme|facilitarme)|necesit(o|amos|aremos)|requerimos|cu[aá]l es su|a nombre de qui[eé]n|puede dejar)/i;
const asksPersonalData = (text) => text.split(/(?<=[.?!\n])\s+/).some((s) =>
  DATA_WORD.test(s) && (REQUEST.test(s) || (/\bsus?\b/i.test(s) && s.includes('?'))));
let blockedByConsent = false;
if (ok && !consented && asksPersonalData(reply)) {
  blockedByConsent = true;
  reply = ctx.consentText;
  waMessage = ctx.consentPrompt;
  const store = $getWorkflowStaticData('global');
  store.consents = store.consents || {};
  store.consents[ctx.from] = { ...(store.consents[ctx.from] || { estado: 'pendiente' }), prompted: true };
}

if (ok) {
  const store = $getWorkflowStaticData('global');
  store.conversations = store.conversations || {};
  const msgs = [
    ...ctx.history,
    { role: 'user', content: ctx.text },
    { role: 'assistant', content: reply },
  ];
  let trimmed = msgs.slice(-ctx.maxTurns);
  if (trimmed.length && trimmed[0].role !== 'user') trimmed = trimmed.slice(1);
  store.conversations[ctx.from] = { messages: trimmed, updatedAt: Date.now() };
}

// Sin consentimiento otorgado no se registra ni se notifica ninguna cita.
const validAppointment = !!appointment && !appointment.raw && consented;

const u = res.usage || {};
return [{
  json: {
    from: ctx.from,
    phoneNumberId: ctx.phoneNumberId,
    reply,
    waMessage,
    blockedByConsent,
    consentStatus: ctx.consentStatus,
    policyVersion: ctx.policyVersion,
    appointment: consented ? appointment : null,
    hasAppointment: validAppointment,
    provider: ctx.provider,
    usage: {
      input_tokens: u.input_tokens ?? res.prompt_eval_count ?? null,
      output_tokens: u.output_tokens ?? res.eval_count ?? null,
      total_ms: res.total_duration ? Math.round(res.total_duration / 1e6) : null,
    },
  },
}];

// Puerta de consentimiento (Ley N.° 29733), determinista: decide SIN la IA cuándo pedir, registrar o
// respetar el consentimiento. Devuelve action "llm" (sigue a la IA) o "reply" (mensaje fijo en waMessage).
const input = $input.first().json;
const from = input.from;
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};
store.consents = store.consents || {};
const policyVersion = ($env.POLICY_VERSION || '').trim() || 'sin-version';
const maxTurns = parseInt($env.CONVERSATION_MAX_MESSAGES || '20', 10);
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;

// Texto fijo de crm/ARQUITECTURA.md §6 (igual al de system_prompt.md).
const CONSENT_TEXT = 'Para gestionar su cita necesitamos usar algunos datos personales (nombre, horario preferido y, opcionalmente, su correo), conforme a la Ley N.° 29733. Puede revisar nuestra política en construccionesyedificacionesjys.com/terminos.html#privacidad. ¿Nos autoriza?';
const ACCEPTED = 'Gracias, hemos registrado su autorización. ¿Me indica su nombre completo, por favor?';
const REJECTED = 'Entendido, no usaremos sus datos personales; puedo darle información general o puede comunicarse directamente al WhatsApp 956 771 681, al teléfono 993 793 224 o al correo Ejuridicojys@gmail.com. Si cambia de opinión, escriba *Acepto*.';

const textMessage = (body) => ({ type: 'text', text: { preview_url: false, body } });
const consentPrompt = {
  type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: CONSENT_TEXT },
    action: { buttons: [
      { type: 'reply', reply: { id: 'consent_si', title: 'Acepto' } },
      { type: 'reply', reply: { id: 'consent_no', title: 'No acepto' } },
    ] },
  },
};

// Estado vigente: un "otorgado" de una versión anterior de la política vuelve a "pendiente".
const consentOf = () => {
  const c = store.consents[from];
  if (!c) return { estado: 'pendiente' };
  if (c.estado === 'otorgado' && c.version !== policyVersion) return { ...c, estado: 'pendiente' };
  return c;
};

// Guarda el intercambio en el historial, para que la IA conozca el contexto en el siguiente turno.
const remember = (userText, assistantText) => {
  let convo = store.conversations[from];
  if (!convo || Date.now() - convo.updatedAt > ttlMs) convo = { messages: [] };
  let msgs = [...convo.messages, { role: 'user', content: userText }, { role: 'assistant', content: assistantText }].slice(-maxTurns);
  if (msgs.length && msgs[0].role !== 'user') msgs = msgs.slice(1);
  store.conversations[from] = { messages: msgs, updatedAt: Date.now() };
};

const out = (extra) => [{ json: {
  from,
  messageId: input.messageId,
  contactName: input.contactName,
  phoneNumberId: input.phoneNumberId,
  text: input.text,
  consentStatus: consentOf().estado,
  policyVersion,
  consentText: CONSENT_TEXT,
  consentPrompt,
  ...extra,
} }];
const reply = (waMessage, visible) => out({ action: 'reply', waMessage, reply: visible });

if (!input.needsAI) return reply(textMessage(input.directReply), input.directReply);

const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9@ ]+/g, ' ').replace(/\s+/g, ' ').trim();
const t = norm(input.text);
const current = consentOf();

// 1) Respuesta al consentimiento: botones o, si se escribe, solo frases inequívocas.
const YES = ['acepto', 'si acepto', 'si, acepto', 'lo acepto', 'si lo acepto', 'autorizo', 'si autorizo', 'acepto gracias'];
const NO = ['no acepto', 'no lo acepto', 'no autorizo', 'no lo autorizo', 'no acepto gracias'];
let decision = null;
if (input.buttonId === 'consent_si') decision = 'otorgado';
else if (input.buttonId === 'consent_no') decision = 'rechazado';
else if (YES.includes(t)) decision = 'otorgado';
else if (NO.includes(t)) decision = 'rechazado';
else if (current.prompted && ['si', 'ok', 'de acuerdo', 'claro', 'si claro', 'si por favor'].includes(t)) decision = 'otorgado';
else if (current.prompted && t === 'no') decision = 'rechazado';

// Un "acepto" escrito cuando ya está otorgado (y no se acaba de preguntar) se deja a la IA.
if (decision && !(decision === current.estado && !input.buttonId && !current.prompted)) {
  store.consents[from] = {
    estado: decision,
    fecha: new Date().toISOString(),
    version: policyVersion,
    canal: input.buttonId ? 'whatsapp_botones' : 'whatsapp_texto',
    prompted: false,
  };
  const msg = decision === 'otorgado' ? ACCEPTED : REJECTED;
  remember(input.text, msg);
  return reply(textMessage(msg), msg);
}

// 2) Sin consentimiento otorgado: si hay intención de cita o de dar datos, se pide el consentimiento
//    con botones y NO se llama a la IA.
const INTENT = /\b(citas?|agendar|agendo|agenda|agendame|programar|reservar|consultas?|reunion|reunirme|reunirnos|abogad[oa]s?|doctora|asesor|asesoria|hablar con|comunicarme con|contactar|contactenme|llamenme|me llamo|mi nombre|mi correo|mi dni|mi telefono|mi celular|mi numero|mi direccion|separar|visita|visitar)\b/;
const EMAIL = /[^\s@]+@[^\s@]+\.[a-z]{2,}/i;
const LONG_NUMBER = /(\d[\s.-]?){8,}/; // DNI o teléfono
const hasData = EMAIL.test(input.text) || LONG_NUMBER.test(input.text) || /\b(me llamo|mi nombre es)\b/.test(t);
if (current.estado !== 'otorgado' && (INTENT.test(t) || hasData)) {
  store.consents[from] = { ...(store.consents[from] || { estado: 'pendiente' }), prompted: true };
  // Minimización: si el mensaje ya traía datos personales, no se guardan antes del consentimiento.
  remember(hasData ? '[Mensaje con datos personales omitido hasta obtener el consentimiento]' : input.text, CONSENT_TEXT);
  return reply(consentPrompt, CONSENT_TEXT);
}

// 3) Todo lo demás va a la IA, que recibe el estado del consentimiento.
return out({ action: 'llm' });
